apiIntegrations.responseShape:
interface GitHubRepo {
  id: number;
  name: string;
  full_name: string;
  owner: { login: string; avatar_url: string; html_url: string };
  html_url: string;
  description: string | null;
  fork: boolean;
  created_at: string;
  updated_at: string;
  pushed_at: string;
  homepage: string | null;
  size: number;
  stargazers_count: number;
  watchers_count: number;
  language: string | null;
  forks_count: number;
  open_issues_count: number;
  license?: { key: string; name: string; spdx_id: string } | null;
  default_branch: string;
  topics?: string[];
}

interface GitHubContributor {
  login: string;
  id: number;
  avatar_url: string;
  html_url: string;
  contributions: number;
  type: 'User' | 'Bot';
}
// endpoint returns an array of GitHubContributor

interface GitHubRelease {
  id: number;
  tag_name: string;
  name: string;
  body?: string;
  published_at: string;
  html_url: string;
  prerelease: boolean;
  draft: boolean;
}
